INSERT INTO `invoice_designs` (`id`, `name`, `javascript`, `pdfmake`) VALUES
(1, 'Clean', 'var GlobalY=0;//Y position of line at current page\n\n	    var client = invoice.client;\n	    var account = invoice.account;\n	    var currencyId = client.currency_id;\n\n	    layout.headerRight = 550;\n	    layout.rowHeight = 15;\n\n	    doc.setFontSize(9);\n\n	    if (invoice.image)\n	    {\n	      var left = layout.headerRight - invoice.imageWidth;\n	      doc.addImage(invoice.image, \'JPEG\', layout.marginLeft, 30);\n	    }\n	  \n	    if (!invoice.is_pro && logoImages.imageLogo1)\n	    {\n	      pageHeight=820;\n	      y=pageHeight-logoImages.imageLogoHeight1;\n	      doc.addImage(logoImages.imageLogo1, \'JPEG\', layout.marginLeft, y, logoImages.imageLogoWidth1, logoImages.imageLogoHeight1);\n	    }\n\n	    doc.setFontSize(9);\n	    SetPdfColor(\'LightBlue\', doc, \'primary\');\n	    displayAccount(doc, invoice, 220, layout.accountTop, layout);\n\n	    SetPdfColor(\'LightBlue\', doc, \'primary\');\n	    doc.setFontSize(\'11\');\n	    doc.text(50, layout.headerTop, (invoice.is_quote ? invoiceLabels.quote : invoiceLabels.invoice).toUpperCase());\n\n\n	    SetPdfColor(\'Black\',doc); //set black color\n	    doc.setFontSize(9);\n\n	    var invoiceHeight = displayInvoice(doc, invoice, 50, 170, layout);\n	    var clientHeight = displayClient(doc, invoice, 220, 170, layout);\n	    var detailsHeight = Math.max(invoiceHeight, clientHeight);\n	    layout.tableTop = Math.max(layout.tableTop, layout.headerTop + detailsHeight + (3 * layout.rowHeight));\n	   \n	    doc.setLineWidth(0.3);        \n	    doc.setDrawColor(200,200,200);\n	    doc.line(layout.marginLeft - layout.tablePadding, layout.headerTop + 6, layout.marginRight + layout.tablePadding, layout.headerTop + 6);\n	    doc.line(layout.marginLeft - layout.tablePadding, layout.headerTop + detailsHeight + 14, layout.marginRight + layout.tablePadding, layout.headerTop + detailsHeight + 14);\n\n	    doc.setFontSize(10);\n	    doc.setFontType(\'bold\');\n	    displayInvoiceHeader(doc, invoice, layout);\n	    var y = displayInvoiceItems(doc, invoice, layout);\n\n	    doc.setFontSize(9);\n	    doc.setFontType(\'bold\');\n\n	    GlobalY=GlobalY+25;\n\n\n	    doc.setLineWidth(0.3);\n	    doc.setDrawColor(241,241,241);\n	    doc.setFillColor(241,241,241);\n	    var x1 = layout.marginLeft - 12;\n	    var y1 = GlobalY-layout.tablePadding;\n\n	    var w2 = 510 + 24;\n	    var h2 = doc.internal.getFontSize()*3+layout.tablePadding*2;\n\n	    if (invoice.discount) {\n	        h2 += doc.internal.getFontSize()*2;\n	    }\n	    if (invoice.tax_amount) {\n	        h2 += doc.internal.getFontSize()*2;\n	    }\n\n	    //doc.rect(x1, y1, w2, h2, \'FD\');\n\n	    doc.setFontSize(9);\n	    displayNotesAndTerms(doc, layout, invoice, y);\n	    y += displaySubtotals(doc, layout, invoice, y, layout.unitCostRight);\n\n\n	    doc.setFontSize(10);\n	    Msg = invoice.is_quote ? invoiceLabels.total : invoiceLabels.balance_due;\n	    var TmpMsgX = layout.unitCostRight-(doc.getStringUnitWidth(Msg) * doc.internal.getFontSize());\n	    \n	    doc.text(TmpMsgX, y, Msg);\n\n	    SetPdfColor(\'LightBlue\', doc, \'primary\');\n	    AmountText = formatMoney(invoice.balance_amount, currencyId);\n	    headerLeft=layout.headerRight+400;\n	    var AmountX = layout.lineTotalRight - (doc.getStringUnitWidth(AmountText) * doc.internal.getFontSize());\n	    doc.text(AmountX, y, AmountText);', '{\"content\":[{\"columns\":[{\"image\":\"$accountLogo\",\"fit\":[120,80]},{\"stack\":\"$accountDetails\",\"margin\":[7,0,0,0]},{\"stack\":\"$accountAddress\"}]},{\"text\":\"$entityTypeUC\",\"margin\":[8,30,8,5],\"style\":\"entityTypeLabel\"},{\"table\":{\"headerRows\":1,\"widths\":[\"auto\",\"auto\",\"*\"],\"body\":[[{\"table\":{\"body\":\"$invoiceDetails\"},\"margin\":[0,0,12,0],\"layout\":\"noBorders\"},{\"stack\":\"$clientDetails\"},{\"text\":\"\"}]]},\"layout\":{\"hLineWidth\":\"$firstAndLast:.5\",\"vLineWidth\":\"$none\",\"hLineColor\":\"#D8D8D8\",\"paddingLeft\":\"$amount:8\",\"paddingRight\":\"$amount:8\",\"paddingTop\":\"$amount:6\",\"paddingBottom\":\"$amount:6\"}},{\"style\":\"invoiceLineItemsTable\",\"table\":{\"headerRows\":1,\"widths\":\"$invoiceLineItemColumns\",\"body\":\"$invoiceLineItems\"},\"layout\":{\"hLineWidth\":\"$notFirst:.5\",\"vLineWidth\":\"$none\",\"hLineColor\":\"#D8D8D8\",\"paddingLeft\":\"$amount:8\",\"paddingRight\":\"$amount:8\",\"paddingTop\":\"$amount:14\",\"paddingBottom\":\"$amount:14\"}},{\"columns\":[\"$notesAndTerms\",{\"table\":{\"widths\":[\"*\",\"40%\"],\"body\":\"$subtotals\"},\"layout\":{\"hLineWidth\":\"$none\",\"vLineWidth\":\"$none\",\"paddingLeft\":\"$amount:34\",\"paddingRight\":\"$amount:8\",\"paddingTop\":\"$amount:4\",\"paddingBottom\":\"$amount:4\"}}]},\"$signature\",{\"stack\":[\"$invoiceDocuments\"],\"style\":\"invoiceDocuments\"}],\"defaultStyle\":{\"font\":\"$bodyFont\",\"fontSize\":\"$fontSize\",\"margin\":[8,4,8,4]},\"footer\":{\"columns\":[{\"text\":\"$invoiceFooter\",\"alignment\":\"left\"}],\"margin\":[40,-20,40,0]},\"styles\":{\"entityTypeLabel\":{\"font\":\"$headerFont\",\"fontSize\":\"$fontSizeLargest\",\"color\":\"$primaryColor:#37a3c6\"},\"primaryColor\":{\"color\":\"$primaryColor:#37a3c6\"},\"accountName\":{\"color\":\"$primaryColor:#37a3c6\",\"bold\":true},\"invoiceDetails\":{\"margin\":[0,0,8,0]},\"accountDetails\":{\"margin\":[0,2,0,2]},\"clientDetails\":{\"margin\":[0,2,0,2]},\"notesAndTerms\":{\"margin\":[0,2,0,2]},\"accountAddress\":{\"margin\":[0,2,0,2]},\"odd\":{\"fillColor\":\"#fbfbfb\"},\"productKey\":{\"color\":\"$primaryColor:#37a3c6\",\"bold\":true},\"subtotalsBalanceDueLabel\":{\"fontSize\":\"$fontSizeLarger\"},\"subtotalsBalanceDue\":{\"fontSize\":\"$fontSizeLarger\",\"color\":\"$primaryColor:#37a3c6\"},\"invoiceNumber\":{\"bold\":true},\"tableHeader\":{\"bold\":true,\"fontSize\":\"$fontSizeLarger\"},\"costTableHeader\":{\"alignment\":\"right\"},\"qtyTableHeader\":{\"alignment\":\"right\"},\"taxTableHeader\":{\"alignment\":\"right\"},\"lineTotalTableHeader\":{\"alignment\":\"right\"},\"invoiceLineItemsTable\":{\"margin\":[0,16,0,16]},\"clientName\":{\"bold\":true},\"cost\":{\"alignment\":\"right\"},\"quantity\":{\"alignment\":\"right\"},\"tax\":{\"alignment\":\"right\"},\"lineTotal\":{\"alignment\":\"right\"},\"subtotals\":{\"alignment\":\"right\"},\"termsLabel\":{\"bold\":true},\"fullheader\":{\"font\":\"$headerFont\",\"fontSize\":\"$fontSizeLargest\",\"bold\":true},\"subheader\":{\"font\":\"$headerFont\",\"fontSize\":\"$fontSizeLarger\"},\"help\":{\"fontSize\":\"$fontSizeSmaller\",\"color\":\"#737373\"},\"invoiceDocuments\":{\"margin\":[7,0,7,0]},\"invoiceDocument\":{\"margin\":[0,10,0,10]}},\"pageMargins\":[40,40,40,60],\"background\":[{\"image\":\"$accountBackground\",\"alignment\":\"center\"}]}'),
(2, 'Bold', '  var GlobalY=0;//Y position of line at current page\n\n			  var client = invoice.client;\n			  var account = invoice.account;\n			  var currencyId = client.currency_id;\n\n			  layout.headerRight = 150;\n			  layout.rowHeight = 15;\n			  layout.headerTop = 125;\n			  layout.tableTop = 300;\n\n			  doc.setLineWidth(0.5);\n\n			  if (NINJA.primaryColor) {\n			    setDocHexFill(doc, NINJA.primaryColor);\n			    setDocHexDraw(doc, NINJA.primaryColor);\n			  } else {\n			    doc.setFillColor(46,43,43);\n			  }  \n\n			  var x1 =0;\n			  var y1 = 0;\n			  var w2 = 595;\n			  var h2 = 100;\n			  doc.rect(x1, y1, w2, h2, \'FD\');\n\n			  if (invoice.image)\n			  {\n			    var left = layout.headerRight - invoice.imageWidth;\n			    doc.addImage(invoice.image, \'JPEG\', layout.marginLeft, 30);\n			  }\n\n			  doc.setLineWidth(0.5);\n			  if (NINJA.primaryColor) {\n			    setDocHexFill(doc, NINJA.primaryColor);\n			    setDocHexDraw(doc, NINJA.primaryColor);\n			  } else {\n			    doc.setFillColor(46,43,43);\n			    doc.setDrawColor(46,43,43);\n			  }  \n\n			  // return doc.setTextColor(240,240,240);//select color Custom Report GRAY Colour\n			  var x1 = 0;//tableLeft-tablePadding ;\n			  var y1 = 750;\n			  var w2 = 596;\n			  var h2 = 94;//doc.internal.getFontSize()*length+length*1.1;//+h;//+tablePadding;\n\n			  doc.rect(x1, y1, w2, h2, \'FD\');\n			  if (!invoice.is_pro && logoImages.imageLogo2)\n			  {\n			      pageHeight=820;\n			      var left = 250;//headerRight ;\n			      y=pageHeight-logoImages.imageLogoHeight2;\n			      var headerRight=370;\n\n			      var left = headerRight - logoImages.imageLogoWidth2;\n			      doc.addImage(logoImages.imageLogo2, \'JPEG\', left, y, logoImages.imageLogoWidth2, logoImages.imageLogoHeight2);\n			  }\n\n			  doc.setFontSize(7);\n			  doc.setFontType(\'bold\');\n			  SetPdfColor(\'White\',doc);\n\n			  displayAccount(doc, invoice, 300, layout.accountTop, layout);\n\n\n			  var y = layout.accountTop;\n			  var left = layout.marginLeft;\n			  var headerY = layout.headerTop;\n\n			  SetPdfColor(\'GrayLogo\',doc); //set black color\n			  doc.setFontSize(7);\n\n			  //show left column\n			  SetPdfColor(\'Black\',doc); //set black color\n			  doc.setFontType(\'normal\');\n\n			  //publish filled box\n			  doc.setDrawColor(200,200,200);\n\n			  if (NINJA.secondaryColor) {\n			    setDocHexFill(doc, NINJA.secondaryColor);\n			  } else {\n			    doc.setFillColor(54,164,152);  \n			  }  \n\n			  GlobalY=190;\n			  doc.setLineWidth(0.5);\n\n			  var BlockLenght=220;\n			  var x1 =595-BlockLenght;\n			  var y1 = GlobalY-12;\n			  var w2 = BlockLenght;\n			  var h2 = getInvoiceDetailsHeight(invoice, layout) + layout.tablePadding + 2;\n\n			  doc.rect(x1, y1, w2, h2, \'FD\');\n\n			  SetPdfColor(\'SomeGreen\', doc, \'secondary\');\n			  doc.setFontSize(\'14\');\n			  doc.setFontType(\'bold\');\n			  doc.text(50, GlobalY, (invoice.is_quote ? invoiceLabels.your_quote : invoiceLabels.your_invoice).toUpperCase());\n\n\n			  var z=GlobalY;\n			  z=z+30;\n\n			  doc.setFontSize(\'8\');        \n			  SetPdfColor(\'Black\',doc);			  \n        var clientHeight = displayClient(doc, invoice, layout.marginLeft, z, layout);\n        layout.tableTop += Math.max(0, clientHeight - 75);\n			  marginLeft2=395;\n\n			  //publish left side information\n			  SetPdfColor(\'White\',doc);\n			  doc.setFontSize(\'8\');\n			  var detailsHeight = displayInvoice(doc, invoice, marginLeft2, z-25, layout) + 75;\n			  layout.tableTop = Math.max(layout.tableTop, layout.headerTop + detailsHeight + (2 * layout.tablePadding));\n\n			  y=z+60;\n			  x = GlobalY + 100;\n			  doc.setFontType(\'bold\');\n\n			  doc.setFontSize(12);\n			  doc.setFontType(\'bold\');\n			  SetPdfColor(\'Black\',doc);\n			  displayInvoiceHeader(doc, invoice, layout);\n\n			  var y = displayInvoiceItems(doc, invoice, layout);\n			  doc.setLineWidth(0.3);\n			  displayNotesAndTerms(doc, layout, invoice, y);\n			  y += displaySubtotals(doc, layout, invoice, y, layout.unitCostRight);\n\n			  doc.setFontType(\'bold\');\n\n			  doc.setFontSize(12);\n			  x += doc.internal.getFontSize()*4;\n			  Msg = invoice.is_quote ? invoiceLabels.total : invoiceLabels.balance_due;\n			  var TmpMsgX = layout.unitCostRight-(doc.getStringUnitWidth(Msg) * doc.internal.getFontSize());\n\n			  doc.text(TmpMsgX, y, Msg);\n\n			  //SetPdfColor(\'LightBlue\',doc);\n			  AmountText = formatMoney(invoice.balance_amount , currencyId);\n			  headerLeft=layout.headerRight+400;\n			  var AmountX = headerLeft - (doc.getStringUnitWidth(AmountText) * doc.internal.getFontSize());\n			  SetPdfColor(\'SomeGreen\', doc, \'secondary\');\n			  doc.text(AmountX, y, AmountText);', '{\"content\":[{\"columns\":[{\"width\":380,\"stack\":[{\"text\":\"$yourInvoiceLabelUC\",\"style\":\"yourInvoice\"},\"$clientDetails\"],\"margin\":[60,100,0,10]},{\"canvas\":[{\"type\":\"rect\",\"x\":0,\"y\":0,\"w\":225,\"h\":\"$invoiceDetailsHeight\",\"r\":0,\"lineWidth\":1,\"color\":\"$primaryColor:#36a498\"}],\"width\":10,\"margin\":[-10,100,0,10]},{\"table\":{\"body\":\"$invoiceDetails\"},\"layout\":\"noBorders\",\"margin\":[0,110,0,0]}]},{\"style\":\"invoiceLineItemsTable\",\"table\":{\"headerRows\":1,\"widths\":\"$invoiceLineItemColumns\",\"body\":\"$invoiceLineItems\"},\"layout\":{\"hLineWidth\":\"$none\",\"vLineWidth\":\"$none\",\"paddingLeft\":\"$amount:8\",\"paddingRight\":\"$amount:8\",\"paddingTop\":\"$amount:14\",\"paddingBottom\":\"$amount:14\"}},{\"columns\":[{\"width\":46,\"text\":\" \"},\"$notesAndTerms\",{\"table\":{\"widths\":[\"*\",\"40%\"],\"body\":\"$subtotals\"},\"layout\":{\"hLineWidth\":\"$none\",\"vLineWidth\":\"$none\",\"paddingLeft\":\"$amount:8\",\"paddingRight\":\"$amount:8\",\"paddingTop\":\"$amount:4\",\"paddingBottom\":\"$amount:4\"}}]},\"$signature\",{\"stack\":[\"$invoiceDocuments\"],\"style\":\"invoiceDocuments\"}],\"footer\":[{\"canvas\":[{\"type\":\"line\",\"x1\":0,\"y1\":0,\"x2\":600,\"y2\":0,\"lineWidth\":100,\"lineColor\":\"$secondaryColor: