}]},{\"canvas\":[{\"type\":\"line\",\"x1\":68,\"y1\":0,\"x2\":135,\"y2\":0,\"lineWidth\":9,\"lineColor\":\"#1d766f\"}]},{\"canvas\":[{\"type\":\"line\",\"x1\":135,\"y1\":0,\"x2\":201,\"y2\":0,\"lineWidth\":9,\"lineColor\":\"#ffb800\"}]},{\"canvas\":[{\"type\":\"line\",\"x1\":201,\"y1\":0,\"x2\":267,\"y2\":0,\"lineWidth\":9,\"lineColor\":\"#bf9730\"}]},{\"canvas\":[{\"type\":\"line\",\"x1\":267,\"y1\":0,\"x2\":333,\"y2\":0,\"lineWidth\":9,\"lineColor\":\"#ac2b50\"}]},{\"canvas\":[{\"type\":\"line\",\"x1\":333,\"y1\":0,\"x2\":399,\"y2\":0,\"lineWidth\":9,\"lineColor\":\"#e60042\"}]},{\"canvas\":[{\"type\":\"line\",\"x1\":399,\"y1\":0,\"x2\":465,\"y2\":0,\"lineWidth\":9,\"lineColor\":\"#ffb800\"}]},{\"canvas\":[{\"type\":\"line\",\"x1\":465,\"y1\":0,\"x2\":532,\"y2\":0,\"lineWidth\":9,\"lineColor\":\"#009d91\"}]},{\"canvas\":[{\"type\":\"line\",\"x1\":532,\"y1\":0,\"x2\":600,\"y2\":0,\"lineWidth\":9,\"lineColor\":\"#ac2b50\"}]}],\"defaultStyle\":{\"fontSize\":\"$fontSize\",\"margin\":[8,4,8,4]},\"styles\":{\"accountName\":{\"color\":\"$secondaryColor:#bb3328\"},\"accountDetails\":{\"margin\":[0,2,0,1]},\"accountAddress\":{\"margin\":[0,2,0,1]},\"clientDetails\":{\"margin\":[0,2,0,1]},\"clientName\":{\"color\":\"$secondaryColor:#bb3328\"},\"even\":{\"fillColor\":\"#E8E8E8\"},\"odd\":{\"fillColor\":\"#F7F7F7\"},\"productKey\":{\"color\":\"$secondaryColor:#bb3328\"},\"lineTotal\":{\"alignment\":\"right\"},\"tableHeader\":{\"bold\":true,\"fontSize\":\"$fontSizeLargest\",\"color\":\"#FFFFFF\"},\"secondTableHeader\":{\"color\":\"$primaryColor:#009d91\"},\"costTableHeader\":{\"alignment\":\"right\"},\"qtyTableHeader\":{\"alignment\":\"right\"},\"lineTotalTableHeader\":{\"alignment\":\"right\"},\"subtotalsBalanceDueLabel\":{\"fontSize\":\"$fontSizeLargest\",\"color\":\"#FFFFFF\",\"bold\":true},\"subtotalsBalanceDue\":{\"fontSize\":\"$fontSizeLargest\",\"bold\":true,\"color\":\"#FFFFFF\",\"alignment\":\"right\"},\"invoiceDetails\":{\"color\":\"#FFFFFF\"},\"invoiceLineItemsTable\":{\"margin\":[0,0,0,16]},\"invoiceDetailBalanceDueLabel\":{\"bold\":true},\"invoiceDetailBalanceDue\":{\"bold\":true},\"fromLabel\":{\"color\":\"$primaryColor:#009d91\"},\"toLabel\":{\"color\":\"$primaryColor:#009d91\"},\"cost\":{\"alignment\":\"right\"},\"quantity\":{\"alignment\":\"right\"},\"tax\":{\"alignment\":\"right\"},\"subtotals\":{\"alignment\":\"right\"},\"subtotalsBalance\":{\"alignment\":\"right\",\"margin\":[0,-25,0,0]},\"termsLabel\":{\"bold\":true,\"margin\":[0,0,0,4]},\"fullheader\":{\"fontSize\":\"$fontSizeLargest\",\"bold\":true},\"subheader\":{\"fontSize\":\"$fontSizeLarger\"},\"help\":{\"fontSize\":\"$fontSizeSmaller\",\"color\":\"#737373\"}},\"pageMargins\":[40,40,40,40],\"background\":[{\"image\":\"$accountBackground\",\"alignment\":\"center\"}]}');
